#pragma once
#include "algebra.hpp"
vector<F> vmul(const vector<F>&a,const vector<F>&b){if(a.empty()||b.empty())return {};if(min(a.size(),b.size())<24){vector<F>c(a.size()+b.size()-1);for(size_t i=0;i<a.size();i++)if(a[i])for(size_t j=0;j<b.size();j++)if(b[j])c[i+j]+=a[i]*b[j];return c;}size_t k=max(a.size(),b.size())/2;vector<F>a0(a.begin(),a.begin()+min(k,a.size())),a1(a.begin()+min(k,a.size()),a.end()),b0(b.begin(),b.begin()+min(k,b.size())),b1(b.begin()+min(k,b.size()),b.end());vector<F>as(max(a0.size(),a1.size())),bs(max(b0.size(),b1.size()));for(size_t i=0;i<as.size();i++)as[i]=(i<a0.size()?a0[i]:F())+(i<a1.size()?a1[i]:F());for(size_t i=0;i<bs.size();i++)bs[i]=(i<b0.size()?b0[i]:F())+(i<b1.size()?b1[i]:F());auto lo=vmul(a0,b0),hi=vmul(a1,b1),mid=vmul(as,bs);for(size_t i=0;i<lo.size();i++)mid[i]-=lo[i];for(size_t i=0;i<hi.size();i++)mid[i]-=hi[i];vector<F>c(a.size()+b.size()-1);for(size_t i=0;i<lo.size();i++)c[i]+=lo[i];for(size_t i=0;i<hi.size();i++)c[i+2*k]+=hi[i];for(size_t i=0;i<mid.size();i++)if(i+k<c.size())c[i+k]+=mid[i];else assert(!mid[i]);return c;}
PF fastmul(const PF&a,const PF&b){return PF(vmul(a.a,b.a));}
